mapper.select:
SELECT distinct t.TRADE_ID tradeId,/**交易编号**/ null outTradeId, /*外部成交编号*/ deal.BOOKSET_ID portfolioId,/**金融产品代码**/ bok.BOOKSET_NAME portfolioName,/**金融产品名称**/ zc.FINPROD_MARKET_ID finprodId, /**资产代码**/ zc.FINPROD_ABBR finprodName,/**资产简称**/ t.TRADE_MARKET tradeMarket,/**交易场所**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.TRADE_AMT tradeAmt,/**交易金额**/ t.SHARE_AMT nums,/**交易份额**/ t.UNIT_CPRICE unitValue,/**单位净值**/ t.CCY ccy,/**币种**/ stl.SETTLE_AMT mdateSettleAmt,/**结算金额**/
stl.MY_ACCT_NO trdAcctId/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE in ('06','07') where t.BUSI_TYPE in ('06','07')
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{portfolioId}
and zc.FINPROD_MARKET_ID IN
#{finprodId}
AND t.PS IN
#{ps}
and t.TRADE_MARKET =#{tradeMarket}
order by t.TRADE_ID desc

select FINPROD_MARKET_ID id, FINPROD_ABBR text, TRADE_MARKET from FIN_PRODUCT
1=1
and FINPROD_TYPE = #{assetType}
AND FINPROD_MARKET_ID = #{initValue}
AND (FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select p.FINPROD_ID id, p.FINPROD_ABBR text from FIN_PRODUCT p
1=1
and FINPROD_TYPE =#{finprodType}
AND p.FINPROD_ID = #{initValue}
AND (FINPROD_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))
